frappe.ui.form.on('Beneficiary Profiling', {
    refresh(frm) {
        add_dropdown_indicators(frm);
    },
    onload(frm) {
        add_dropdown_indicators(frm);
    }
});

function add_dropdown_indicators(frm) {
    // Add CSS once
    if (!document.getElementById('dropdown-indicator-style')) {
        const style = document.createElement('style');
        style.id = 'dropdown-indicator-style';
        style.textContent = `
            .frappe-control[data-fieldtype="Link"] .control-input,
            .frappe-control[data-fieldtype="Select"] .control-input,
            .frappe-control[data-fieldtype="Autocomplete"] .control-input,
            .frappe-control[data-fieldtype="Table MultiSelect"] .control-input {
                position: relative;
            }
            .frappe-control[data-fieldtype="Link"] .control-input::after,
            .frappe-control[data-fieldtype="Select"] .control-input::after,
            .frappe-control[data-fieldtype="Autocomplete"] .control-input::after,
            .frappe-control[data-fieldtype="Table MultiSelect"] .control-input::after {
                content: '\\25BE';
                position: absolute;
                right: 10px;
                top: 50%;
                transform: translateY(-50%);
                color: #1565C0;
                font-size: 14px;
                pointer-events: none;
                z-index: 1;
            }
            .frappe-control[data-fieldtype="Link"] .control-label,
            .frappe-control[data-fieldtype="Select"] .control-label,
            .frappe-control[data-fieldtype="Autocomplete"] .control-label,
            .frappe-control[data-fieldtype="Table MultiSelect"] .control-label {
                color: #1565C0 !important;
            }
            .frappe-control[data-fieldtype="Link"] input,
            .frappe-control[data-fieldtype="Select"] select,
            .frappe-control[data-fieldtype="Autocomplete"] input {
                padding-right: 28px !important;
            }
        `;
        document.head.appendChild(style);
    }
}

